import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { emptyRecordKeys, ENVELOPE_KEYS, JSON_LIMITS, jsonBlocks, RECORD_KINDS, recordKeys, scanJson, type RecordKeys } from "./records.ts";

// Conformance with slice A's own parser. The corpus is slice A's, copied unmodified from bayfold/monorepo
// at 71e1eeee75 (tools/tests/data/work-records-conformance.json, generated by A's
// tools/tests/generate_work_records_conformance.py from its real tools/work_records.py; reviewed and
// approved at that exact head, review 5836292885). This file contains no grammar of its own. To move
// to a newer reviewed corpus, copy A's file over this one and update the pin below.
const PINNED = {
  sha256: "e436ca30bdc6cac89fdbfb2b628d8a3cd086aa06293bce7af521644256cc0f1e",
  parser: { path: "tools/work_records.py", git_blob_sha1: "377d0071b33fcadf5a44e081b3a24cd5ea578666" },
};

interface Verdict {
  readonly role: "record" | "request" | null;
  readonly accepted?: boolean;
  readonly code?: string;
  readonly fields?: Omit<RecordKeys, "record_marker">;
  readonly routing_fields?: Omit<RecordKeys, "record_marker">;
}
const corpusText = readFileSync(new URL("./conformance/work-records.json", import.meta.url), "utf8");
const corpus = JSON.parse(corpusText) as {
  readonly source: { readonly path: string; readonly git_blob_sha1: string; readonly sha256: string };
  readonly kinds: readonly string[];
  readonly envelope_keys: readonly string[];
  readonly max_json_bytes: number;
  readonly max_json_int_digits: number;
  readonly max_json_depth: number;
  readonly cases: ReadonlyArray<{ readonly name: string; readonly body: string; readonly a: Verdict }>;
};

test("the corpus is A's reviewed one, unmodified, with its parser's provenance", () => {
  assert.equal(createHash("sha256").update(corpusText).digest("hex"), PINNED.sha256);
  assert.equal(corpus.source.path, PINNED.parser.path);
  assert.equal(corpus.source.git_blob_sha1, PINNED.parser.git_blob_sha1);
});

test("the kinds and envelope keys are A's", () => {
  assert.deepEqual([...RECORD_KINDS].sort(), [...corpus.kinds]);
  assert.deepEqual([...ENVELOPE_KEYS], [...corpus.envelope_keys]);
});

test(`routing keys agree with A's parser on every conformance case (parser blob ${corpus.source.git_blob_sha1.slice(0, 10)})`, () => {
  assert.equal(corpus.cases.length, 50);
  for (const { name, body, a } of corpus.cases) {
    const marker = a.role === null ? null : `bayfold-${a.role}:v1`;
    // Accepted by A: its fields. Refused only for payload/provenance contents (A's `payload` code):
    // still routed, by design; the writer refuses it. Any other refusal: the marker alone.
    const fields = a.accepted === true ? a.fields : a.code === "payload" ? a.routing_fields : undefined;
    if (a.code === "payload") assert.ok(a.routing_fields !== undefined, `${name}: A's payload verdict carries routing_fields`);
    const expected: RecordKeys = { ...emptyRecordKeys(), record_marker: marker, ...(fields ?? {}) };
    assert.deepEqual(recordKeys(body), expected, `${name}: A says ${JSON.stringify(a)}`);
  }
});

test("bodies over the UTF-16 parsing limit retain markers without parsing envelopes", () => {
  const valid = corpus.cases.find((c) => c.name === "request rendered by A")?.body ?? "";
  const record = corpus.cases.find((c) => c.name === "record rendered by A")?.body ?? "";
  assert.ok(recordKeys(valid).record_kind !== null);
  assert.ok(recordKeys(record).record_kind !== null);
  assert.deepEqual(recordKeys(valid + "x".repeat(70_000)), { ...emptyRecordKeys(), record_marker: "bayfold-request:v1" });
  for (const prefix of ["x".repeat(70_000), "😀".repeat(33_000)]) {
    for (const [body, marker] of [
      [valid, "bayfold-request:v1"],
      [record, "bayfold-record:v1"],
      ["<!-- bayfold-record:v1 -->\nnot an envelope", "bayfold-record:v1"],
      [valid + record, "bayfold-record:v1"],
    ] as const) {
      assert.deepEqual(recordKeys(prefix + "\n" + body), { ...emptyRecordKeys(), record_marker: marker });
    }
    assert.deepEqual(recordKeys(prefix), emptyRecordKeys());
  }
  assert.deepEqual(recordKeys(null), emptyRecordKeys());
});

test("the JSON scan sees repeated keys and raw top-level tokens", () => {
  assert.equal(scanJson('{"a": 1, "b": {"a": 2}}').duplicate, false);
  assert.equal(scanJson('{"a": 1, "b": {"c": 2, "c": 3}}').duplicate, true);
  assert.equal(scanJson('{"a": 1, "\\u0061": 2}').duplicate, true);
  assert.equal(scanJson('{"s": "x\\"y", "s2": "\\\\", "n": [1, {"k": 1}], "k": 1}').duplicate, false);
  const top = scanJson('{"schema": 1.0, "sequence": 12, "o": {"sequence": 1}, "t": true, "s": "1"}').topLevel;
  assert.equal(top.get("schema"), "1.0");
  assert.equal(top.get("sequence"), "12");
  assert.equal(top.get("o"), undefined);
  assert.equal(top.get("t"), "true");
  assert.equal(top.get("s"), '"1"');
});

test("an escaped lone surrogate makes the JSON invalid, as in A's loader", () => {
  const valid = corpus.cases.find((c) => c.name === "request rendered by A")?.body ?? "";
  assert.ok(recordKeys(valid).record_kind !== null);
  const broken = valid.replace('"owner": "builder-4045"', '"owner": "builder-\\ud800"');
  assert.notEqual(broken, valid);
  assert.deepEqual(recordKeys(broken), { ...emptyRecordKeys(), record_marker: "bayfold-request:v1" });
  // A paired surrogate escape is fine.
  assert.ok(recordKeys(valid.replace('"owner": "builder-4045"', '"owner": "builder-\\ud83d\\ude00"')).record_kind !== null);
});

// Verdicts of A's parser at 5688f6aa2a, b1168eca05 and 71e1eeee75 (the same) under Python 3.12.13 for
// these bodies (a `probe` key added to the payload of "request rendered by A"): `payload` routes with the
// envelope fields, `json` does not.
const withPayloadProbe = (raw: string): string => {
  const valid = corpus.cases.find((c) => c.name === "request rendered by A")?.body ?? "";
  const probed = valid.replace('"payload": {', `"payload": {"probe": ${raw}, `);
  assert.notEqual(probed, valid);
  return probed;
};
const routed = (): RecordKeys => {
  const accepted = corpus.cases.find((c) => c.name === "request rendered by A")?.a;
  return { ...emptyRecordKeys(), record_marker: "bayfold-request:v1", ...(accepted?.fields ?? {}) };
};
const markerOnly = (): RecordKeys => ({ ...emptyRecordKeys(), record_marker: "bayfold-request:v1" });

test("E's JSON limits are the ones in A's corpus header", () => {
  assert.deepEqual(JSON_LIMITS, {
    maxJsonBytes: corpus.max_json_bytes,
    maxJsonIntDigits: corpus.max_json_int_digits,
    maxJsonDepth: corpus.max_json_depth,
  });
});

test("an integer literal over A's digit limit makes the JSON invalid anywhere in it; a float has no limit", () => {
  const digits = corpus.max_json_int_digits;
  assert.deepEqual(recordKeys(withPayloadProbe("1".repeat(digits))), routed(), `${digits} digits: A says payload`);
  assert.deepEqual(recordKeys(withPayloadProbe(`-${"1".repeat(digits)}`)), routed(), `-${digits} digits: A says payload`);
  assert.deepEqual(recordKeys(withPayloadProbe("1".repeat(digits + 1))), markerOnly(), `${digits + 1} digits: A says json`);
  assert.deepEqual(recordKeys(withPayloadProbe(`-${"1".repeat(digits + 1)}`)), markerOnly(), `-${digits + 1} digits: A says json`);
  assert.deepEqual(recordKeys(withPayloadProbe(`[{"n": [${"1".repeat(digits + 1)}]}]`)), markerOnly(), "nested: A says json");
  assert.deepEqual(recordKeys(withPayloadProbe("1".repeat(4301))), markerOnly(), "4301 digits: A says json");
  assert.deepEqual(recordKeys(withPayloadProbe(`${"1".repeat(5000)}.5`)), routed(), "5000-digit fraction: A says payload");
  assert.deepEqual(recordKeys(withPayloadProbe(`${"1".repeat(5000)}e2`)), routed(), "5000-digit exponent: A says payload");
  assert.equal(scanJson(`{"a": [1, ${"9".repeat(digits + 1)}]}`).longInteger, true);
  assert.equal(scanJson(`{"a": "${"9".repeat(digits + 1)}", "b": ${"9".repeat(digits)}}`).longInteger, false);
});

test("nesting over A's depth limit makes the JSON invalid; brackets in strings do not nest", () => {
  const depth = corpus.max_json_depth;
  // The probe sits in `payload`, two levels below the root, so k brackets reach depth 2 + k.
  const atLimit = depth - 2;
  assert.deepEqual(recordKeys(withPayloadProbe(`${"[".repeat(atLimit)}${"]".repeat(atLimit)}`)), routed(), `depth ${depth}: A says payload`);
  assert.deepEqual(recordKeys(withPayloadProbe(`${"[".repeat(atLimit + 1)}${"]".repeat(atLimit + 1)}`)), markerOnly(), `depth ${depth + 1}: A says json`);
  assert.deepEqual(recordKeys(withPayloadProbe(`${'{"a": '.repeat(atLimit + 1)}1${"}".repeat(atLimit + 1)}`)), markerOnly(), `depth ${depth + 1} in objects: A says json`);
  for (const k of [3999, 7998]) {
    assert.deepEqual(recordKeys(withPayloadProbe(`${"[".repeat(k)}${"]".repeat(k)}`)), markerOnly(), `depth ${k + 2}: A says json`);
  }
  assert.deepEqual(recordKeys(withPayloadProbe(`"${"[".repeat(100)}"`)), routed(), "brackets inside a string: A says payload");
  assert.deepEqual(recordKeys(withPayloadProbe(`"\\"${"[".repeat(100)}"`)), routed(), "brackets after an escaped quote: A says payload");
  assert.deepEqual(recordKeys(withPayloadProbe(`${"[".repeat(atLimit)}"\\ud800"${"]".repeat(atLimit)}`)), markerOnly(), "a lone surrogate at the limit: A says json");
  // With schema and sequence first in the text, only the depth check refuses it (the scan stops at the
  // limit, so in A's rendered order the integer check would refuse it as well).
  const valid = corpus.cases.find((c) => c.name === "request rendered by A")?.body ?? "";
  const reordered = valid.replace('  "schema": 1,\n  "sequence": 1,\n', "").replace("{\n", '{\n  "schema": 1,\n  "sequence": 1,\n');
  assert.equal(reordered.match(/"schema"/g)?.length, 1);
  const probeIn = (body: string, k: number) => body.replace('"payload": {', `"payload": {"probe": ${"[".repeat(k)}${"]".repeat(k)}, `);
  assert.deepEqual(recordKeys(reordered), routed(), "schema and sequence first: A accepts it");
  assert.deepEqual(recordKeys(probeIn(reordered, atLimit)), routed(), `schema and sequence first, depth ${depth}: A says payload`);
  assert.deepEqual(recordKeys(probeIn(reordered, atLimit + 1)), markerOnly(), `schema and sequence first, depth ${depth + 1}: A says json`);
  assert.equal(scanJson(`${"[".repeat(depth)}${"]".repeat(depth)}`).tooDeep, false, "the root counts: exactly the limit");
  assert.equal(scanJson(`${"[".repeat(depth + 1)}${"]".repeat(depth + 1)}`).tooDeep, true);
});

test("json blocks are found as A's fence_blocks finds them", () => {
  // [body, from, A's FENCE.findall(body, from) at 5688f6aa2a, equal to its fence_blocks(body, from) at b1168eca05]
  const cases: Array<[string, number, string[]]> = [
    ["```json\n```\n", 0, []],
    ["```json\n\n```", 0, [""]],
    ["```json\n{}\n```", 0, ["{}"]],
    ["```json\n```json\n{}\n```", 0, ["```json\n{}"]],
    ["```json\n{}\n```\n```json\n{}\n```", 0, ["{}", "{}"]],
    ["```json\n{}\n```\n```json\n{}", 0, ["{}"]],
    ["```json\r\n{}\r\n```\r\n", 0, []],
    ["```json \t\n{}\n``` \t", 0, ["{}"]],
    ["x```json\n{}\n```", 0, []],
    [" ```json\n{}\n```", 0, []],
    ["```json\n{}\n ```", 0, []],
    ["```json", 0, []],
    ["ab```json\n{}\n```", 2, []],
    ["ab\n```json\n{}\n```", 2, ["{}"]],
  ];
  for (const [body, from, expected] of cases) assert.deepEqual(jsonBlocks(body, from), expected, JSON.stringify([body, from]));
});

test("the line scan finds what the earlier regex found on random fence layouts", () => {
  // The regex this replaced: same grammar, but it retried its lazy match from every unclosed opener.
  const regex = /(?<=^|\n)```json[ \t]*\n([\s\S]*?)\n```[ \t]*(?=\n|$)/g;
  const fragments = ["```json", "```json \t", "```", "``` ", "```jsonx", " ```json", "```json\r", "```\r", "{\"a\": 1}", "", "x"];
  let seed = 0x5eed;
  const next = () => {
    seed = (Math.imul(seed, 1103515245) + 12345) >>> 0;
    return seed / 4294967296;
  };
  for (let n = 0; n < 2000; n += 1) {
    const lines = Array.from({ length: 1 + Math.floor(next() * 10) }, () => fragments[Math.floor(next() * fragments.length)] ?? "");
    const body = lines.join("\n") + (next() < 0.5 ? "\n" : "");
    // As recordKeys calls it: from the end of a line, or from the start.
    const ends = [0, ...[...body.matchAll(/\n/g)].map((m) => m.index ?? 0)];
    const from = ends[Math.floor(next() * ends.length)] ?? 0;
    const expected = [...body.slice(from).matchAll(regex)].map((m) => m[1] ?? "");
    assert.deepEqual(jsonBlocks(body, from), expected, JSON.stringify([body, from]));
  }
});

test("a body of unclosed fence openers is scanned in linear time", () => {
  const marker = "<!-- bayfold-request:v1 -->\n";
  const body = marker + "```json\n".repeat(Math.floor((65_536 - marker.length) / 8));
  assert.ok(body.length <= 65_536);
  assert.deepEqual(recordKeys(body), markerOnly());
  // The regex took about 470 ms of CPU per call on this body; the line scan takes a few ms.
  const times: number[] = [];
  for (let i = 0; i < 5; i += 1) {
    const before = process.cpuUsage();
    recordKeys(body);
    const used = process.cpuUsage(before);
    times.push((used.user + used.system) / 1000);
  }
  times.sort((a, b) => a - b);
  assert.ok((times[2] ?? Infinity) < 50, `median ${times[2] ?? "?"} ms CPU`);
});

test("a work reference longer than GitHub allows does not route, so the event stays small", () => {
  const valid = corpus.cases.find((c) => c.name === "request rendered by A")?.body ?? "";
  const long = valid.replaceAll("bayfold/monorepo#4045", `bayfold/${"m".repeat(5000)}#4045`);
  assert.deepEqual(recordKeys(long), { ...emptyRecordKeys(), record_marker: "bayfold-request:v1" });
  assert.equal(recordKeys(valid.replaceAll("#4045", "#1234567890")).record_work, null, "issue number over 9 digits");
});
